-- Run ONCE in a Snowsight worksheet as ACCOUNTADMIN, AFTER sql/ddl.sql.
USE ROLE ACCOUNTADMIN;
CREATE ROLE IF NOT EXISTS FC_ROLE;
GRANT USAGE, OPERATE ON WAREHOUSE FC_WH TO ROLE FC_ROLE;
GRANT USAGE ON DATABASE FLASHCROWD TO ROLE FC_ROLE;
GRANT USAGE, CREATE TABLE, CREATE VIEW, CREATE STAGE ON SCHEMA FLASHCROWD.CORE TO ROLE FC_ROLE;
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE ON ALL TABLES IN SCHEMA FLASHCROWD.CORE TO ROLE FC_ROLE;
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE ON FUTURE TABLES IN SCHEMA FLASHCROWD.CORE TO ROLE FC_ROLE;
GRANT SELECT ON FUTURE VIEWS IN SCHEMA FLASHCROWD.CORE TO ROLE FC_ROLE;
-- Service user: key-pair auth only (password logins are blocked by Snowflake)
CREATE USER IF NOT EXISTS FC_APP
  TYPE = SERVICE
  DEFAULT_ROLE = FC_ROLE
  DEFAULT_WAREHOUSE = FC_WH
  DEFAULT_NAMESPACE = FLASHCROWD.CORE
  RSA_PUBLIC_KEY = '';
GRANT ROLE FC_ROLE TO USER FC_APP;
GRANT ROLE FC_ROLE TO ROLE SYSADMIN;
